import {migrateMission} from './progress/model.js';
import {initial} from '../data/seed.js';
export const KEY='bibaboo-v02';let failed=false;function read(k){try{return JSON.parse(localStorage.getItem(k)||'null')}catch{return null}}
export const state=read(KEY)||initial();if(!read(KEY)){const old=read('bibaboo-v01');if(old){state.tasks=old.tasks||state.tasks;state.chapters=old.chapters||state.chapters;state.deadline=old.deadline||state.deadline;state.sessions=(old.sessions||[]).map((s,i)=>({...s,id:'old'+i,cat:({'论文':'THESIS','葡语':'PORTUGUESE','翻译':'TRANSLATION'})[s.cat]||'OTHER'}));if(old.draft)state.legacyDraft=old.draft;state.vocab.forEach(v=>v.saved=v.saved||old.stars?.includes(v.word));for(const word of (old.stars||[])){if(!state.vocab.some(v=>v.word===word))state.vocab.push({id:'legacy-'+word,word,pos:'V0.1 收藏',zh:({'saudade':'思念；怀念','aos poucos':'一点一点地','aliás':'其实；顺便说一句','dar conta de':'能够应付；完成'})[word]||'',pt:'',sentence:'',collocation:'',synonyms:'',register:'',c1:'从 V0.1 保留的个人收藏。',tags:'V0.1',saved:true,reviews:0})}if(old.reads)state.papers.forEach((p,i)=>{if(old.reads[i]){p.status='已读';p.progress=100}});}}
// Preserve V0.1 collections even if an earlier V0.2 preview already created a save.
if(!state.legacyCollectionsMigrated){const legacy=read('bibaboo-v01');if(legacy){if(legacy.draft&&!state.legacyDraft)state.legacyDraft=legacy.draft;if(legacy.draft&&state.drafts['n1-PT-ZH']===legacy.draft)delete state.drafts['n1-PT-ZH'];for(const word of legacy.stars||[]){if(!state.vocab.some(v=>v.word===word))state.vocab.push({id:'legacy-'+word,word,pos:'V0.1 收藏',zh:({'saudade':'思念；怀念','aos poucos':'一点一点地','aliás':'其实；顺便说一句','dar conta de':'能够应付；完成'})[word]||'',pt:'',sentence:'',collocation:'',synonyms:'',register:'',c1:'从 V0.1 保留的个人收藏。',tags:'V0.1',saved:true,reviews:0})}}state.legacyCollectionsMigrated=true;}
export function save(){try{localStorage.setItem(KEY,JSON.stringify(state));failed=false;return true}catch{failed=true;globalThis.dispatchEvent?.(new CustomEvent('storage-failed'));return false}}
export function storageFailed(){return failed}export const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);export function dateKey(date=new Date()){return new Date(date).toLocaleDateString('sv-SE')}
export function update(fn){fn(state);save()}export function esc(v=''){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}export const fmt=m=>`${String(Math.floor(m/60)).padStart(2,'0')}H ${String(Math.round(m%60)).padStart(2,'0')}M`;
export function totalProgress(){return Math.round(state.chapters.reduce((a,b)=>a+Number(b),0)/state.chapters.length)}
export function focusRecords(range='today',now=new Date()){let start=new Date(now);start.setHours(0,0,0,0);if(range==='week')start.setDate(start.getDate()-(start.getDay()+6)%7);if(range==='month')start.setDate(1);if(range==='year')start=new Date(now.getFullYear(),0,1);return state.sessions.filter(s=>s.date>=dateKey(start)&&s.date<=dateKey(now))}
export function streak(now=new Date()){const dates=new Set(state.sessions.map(s=>s.date));let d=new Date(now),n=0;if(!dates.has(dateKey(d)))d.setDate(d.getDate()-1);while(dates.has(dateKey(d))){n++;d.setDate(d.getDate()-1)}return n}
export function minutes(range){return focusRecords(range).reduce((a,s)=>a+s.minutes,0)}
// A one-time full pre-migration backup stays in this browser; never clear the original key.
if(!state.missionSchemaVersion){try{if(!localStorage.getItem('bibaboo-v02-before-mission'))localStorage.setItem('bibaboo-v02-before-mission',JSON.stringify(state))}catch{/* Main save will report storage availability. */}}
migrateMission(state);
save();
